            => new BossMoveProfile((white ? "boss_white_night." : "boss_dark_moon.") + id, white ? WhiteNightSetId : DarkMoonSetId, new Txt(ja, en, zh), channels, actions);
        internal static BossMoveProfile[] CreateInkMoves() => new[]
        {
            InkProfile(true,"weapon","通常攻撃が3回命中するごとに、命中地点に予告を出し、0.65秒後に半径2.5mの範囲へ掌撃を放って、攻撃力・魔力の高い方の25%のダメージを与える。再発動まで3秒かかる。", "Every 3 basic attack hits, show a warning at the hit location for 0.65 seconds, then unleash a palm strike in a 2.5m radius dealing 25% of whichever is higher: your Attack or Ability Power. Cooldown: 3 seconds.", "通常攻击每命中3次，在命中地点显示预警，0.65秒后向半径2.5m范围释放掌击，造成相当于攻击力与法术强度中较高一方25%的伤害。冷却3秒。",new[]{InkChannel("LotusPalm",BossInkBalance.LotusPalmValue)},
                new BossAction(BossEvent.MainHit,BossMechanism.ShapeAttack,BossPayload.Damage,"LotusPalm",anchor:BossAnchor.Hit,cooldownMillis:BossInkBalance.WhiteWeaponA0CooldownMillis,delayMillis:BossInkBalance.WhiteWeaponA0DelayMillis,mainHits:BossInkBalance.WhiteWeaponA0MainHits,maxInstances:BossInkBalance.WhiteWeaponA0MaxInstances,radiusMilli:BossInkBalance.WhiteWeaponA0RadiusMilli,element:BossElement.Light)),
            InkProfile(true,"armor","ダメージを受けた後、自身の位置に半径2mの領域を1.5秒間展開する。領域内にいる自身は攻撃力・魔力の高い方の15%の障壁を1回、1.5秒間得る。再発動まで8秒かかる。", "After you take damage, create an area with a 2m radius at your position for 1.5 seconds. While you are inside, it grants you a shield once, lasting 1.5 seconds and equal to 15% of whichever is higher: your Attack or Ability Power. Cooldown: 8 seconds.", "受到伤害后，在自身位置展开半径2m的领域，持续1.5秒。领域内的自身获得1次相当于攻击力与法术强度中较高一方15%的护盾，持续1.5秒。冷却8秒。",new[]{InkChannel("LotusHaven",BossInkBalance.LotusHavenValue,kind:BossCoefficientKind.Shield)},
                new BossAction(BossEvent.NativeDamageTaken,BossMechanism.Field,BossPayload.Shield,"LotusHaven",cooldownMillis:BossInkBalance.WhiteArmorA0CooldownMillis,lifetimeMillis:BossInkBalance.WhiteArmorA0LifetimeMillis,maxInstances:BossInkBalance.WhiteArmorA0MaxInstances,maxTargets:BossInkBalance.WhiteArmorA0MaxTargets,radiusMilli:BossInkBalance.WhiteArmorA0RadiusMilli,magnitudeMilli:BossInkBalance.WhiteArmorA0MagnitudeMilli)),
            InkProfile(true,"charm","記憶を使ったとき、自身の位置に、半径が3mから2mへ1.2秒かけて縮んでいく領域を展開する。領域が終わるとき、範囲内にいる自身と最も近い味方ヒーロー1人は、それぞれ攻撃力・魔力の高い方の12%の障壁を2秒間得る。再発動まで6秒かかる。", "When you use a memory, create an area at your position that shrinks from a 3m radius to 2m over 1.2 seconds. When it ends, grant you and the nearest allied hero inside a shield each, lasting 2 seconds and equal to 12% of whichever is higher: your Attack or Ability Power. Cooldown: 6 seconds.", "使用记忆时，在自身位置展开领域，其半径在1.2秒内从3m缩至2m。领域结束时，范围内的自身及最近的1名友方英雄各获得相当于攻击力与法术强度中较高一方12%的护盾，持续2秒。冷却6秒。",new[]{InkChannel("LotusSafe",BossInkBalance.LotusSafeValue,kind:BossCoefficientKind.Shield)},
                new BossAction(BossEvent.MemoryUse,BossMechanism.Field,BossPayload.Shield,"LotusSafe",cooldownMillis:BossInkBalance.WhiteCharmA0CooldownMillis,delayMillis:BossInkBalance.WhiteCharmA0DelayMillis,lifetimeMillis:BossInkBalance.WhiteCharmA0LifetimeMillis,maxInstances:BossInkBalance.WhiteCharmA0MaxInstances,maxTargets:BossInkBalance.WhiteCharmA0MaxTargets,radiusMilli:BossInkBalance.WhiteCharmA0RadiusMilli,widthMilli:BossInkBalance.WhiteCharmA0WidthMilli,magnitudeMilli:BossInkBalance.WhiteCharmA0MagnitudeMilli)),
            InkProfile(true,"head","通常攻撃が5回命中するごとに、-30°、0°、+30°の3方向へ、それぞれ0秒後、0.2秒後、0.4秒後に、範囲5m・角度60°の光の扇状波を放ち、攻撃力・魔力の高い方の10%のダメージを与える。再発動まで5秒かかり、続けて放つのは1連撃だけである。", "Every 5 basic attack hits, release 3 Light waves in fans with a 5m range and a 60-degree angle, directed at -30, 0, and +30 degrees, after 0, 0.2, and 0.4 seconds respectively. Each deals 10% of whichever is higher: your Attack or Ability Power. Cooldown: 5 seconds. Only one sequence can occur at a time.", "通常攻击每命中5次，分别于0秒后、0.2秒后、0.4秒后向-30°、0°、+30°三个方向释放射程5m、角度60°的光之扇形波，各造成相当于攻击力与法术强度中较高一方10%的伤害。冷却5秒，同时只能进行1轮连击。",new[]{InkChannel("LotusWave",BossInkBalance.LotusWaveValue)},
