            InkProfile(false,"armor","ダメージを受けた後、攻撃者の方向の8m以内の地点に予告を出し、0.8秒後に範囲2mへ槌を叩きつけて、攻撃力・魔力の高い方の20%のダメージを与える。再発動まで8秒かかり、無敵にはならない。", "After you take damage, show a warning for 0.8 seconds at a location within 8m toward the attacker, then slam a hammer in a 2m area, dealing 20% of whichever is higher: your Attack or Ability Power. Cooldown: 8 seconds. This does not grant invulnerability.", "受到伤害后，在攻击者方向8m以内的地点显示预警，0.8秒后向2m范围砸下巨锤，造成相当于攻击力与法术强度中较高一方20%的伤害。冷却8秒，不会带来无敌。",new[]{InkChannel("MoonWrath",BossInkBalance.MoonWrathValue)},
                new BossAction(BossEvent.NativeDamageTaken,BossMechanism.ShapeAttack,BossPayload.Damage,"MoonWrath",anchor:BossAnchor.Hit,cooldownMillis:BossInkBalance.DarkArmorA0CooldownMillis,delayMillis:BossInkBalance.DarkArmorA0DelayMillis,maxInstances:BossInkBalance.DarkArmorA0MaxInstances,radiusMilli:BossInkBalance.DarkArmorA0RadiusMilli,rangeMilli:BossInkBalance.DarkArmorA0RangeMilli,element:BossElement.Dark)),
            InkProfile(false,"charm","記憶を使ったとき、照準方向へ弾速12m/秒で投槍を1本放つ。投槍は長さ8m・幅0.5mの軌道上を、最初に当たる敵か壁まで進み、攻撃力・魔力の高い方の20%のダメージを与える。再発動まで5秒かかる。", "When you use a memory, throw one spear in your aim direction at 12m/s, along a path 8m long and 0.5m wide. It stops at the first enemy or wall it hits and deals 20% of whichever is higher: your Attack or Ability Power. Cooldown: 5 seconds.", "使用记忆时，向瞄准方向以12m/秒投出1支长矛，沿长8m、宽0.5m的轨迹前进，在首次命中敌人或墙壁时停止，造成相当于攻击力与法术强度中较高一方20%的伤害。冷却5秒。",new[]{InkChannel("MoonThrow",BossInkBalance.MoonThrowValue)},
                new BossAction(BossEvent.MemoryUse,BossMechanism.Projectile,BossPayload.Damage,"MoonThrow",cooldownMillis:BossInkBalance.DarkCharmA0CooldownMillis,maxInstances:BossInkBalance.DarkCharmA0MaxInstances,rangeMilli:BossInkBalance.DarkCharmA0RangeMilli,widthMilli:BossInkBalance.DarkCharmA0WidthMilli,speedMilli:BossInkBalance.DarkCharmA0SpeedMilli,firstHitOnly:true,element:BossElement.Dark)),
            InkProfile(false,"head","通常攻撃が5回命中するごとに、命中地点（最大8m）へ弾速12m/秒の剣弾を放つ。剣弾は終点の半径2mだけに攻撃力・魔力の高い方の25%のダメージを与え、壁で消える。再発動まで5秒かかり、召喚物ではない。", "Every 5 basic attack hits, fire a sword projectile at the hit location, up to 8m away, at 12m/s. It deals damage only in a 2m radius at its destination, equal to 25% of whichever is higher: your Attack or Ability Power. It disappears on hitting a wall. Cooldown: 5 seconds. This is not a summon.", "通常攻击每命中5次，向命中地点（最远8m）以12m/秒发射剑弹。剑弹仅在终点半径2m内造成相当于攻击力与法术强度中较高一方25%的伤害，撞墙时消失。冷却5秒，不视为召唤物。",new[]{InkChannel("MoonEgo",BossInkBalance.MoonEgoValue)},
                new BossAction(BossEvent.MainHit,BossMechanism.Projectile,BossPayload.Damage,"MoonEgo",anchor:BossAnchor.Hit,cooldownMillis:BossInkBalance.DarkHeadA0CooldownMillis,mainHits:BossInkBalance.DarkHeadA0MainHits,maxInstances:BossInkBalance.DarkHeadA0MaxInstances,radiusMilli:BossInkBalance.DarkHeadA0RadiusMilli,rangeMilli:BossInkBalance.DarkHeadA0RangeMilli,widthMilli:BossInkBalance.DarkHeadA0WidthMilli,speedMilli:BossInkBalance.DarkHeadA0SpeedMilli,element:BossElement.Dark)),
            InkProfile(false,"hands","通常攻撃が4回命中するごとに、前方の長さ5m・幅0.8mの直線状に攻撃力・魔力の高い方の20%のダメージを与え、ボス以外で行動妨害が効く敵だけを、前方へ最大1m押し出す。再発動まで4秒かかり、地形は通過しない。", "Every 4 basic attack hits, deal damage along a forward line 5m long and 0.8m wide, equal to 20% of whichever is higher: your Attack or Ability Power, and push enemies forward up to 1m, excluding bosses and enemies immune to crowd control. Cooldown: 4 seconds. Enemies cannot pass through terrain.", "通常攻击每命中4次，向前方长5m、宽0.8m的直线造成相当于攻击力与法术强度中较高一方20%的伤害，并将非首领且不免疫控制的敌人向前推开最多1m。冷却4秒，敌人无法穿过地形。",new[]{InkChannel("MoonCarry",BossInkBalance.MoonCarryValue)},
                new BossAction(BossEvent.MainHit,BossMechanism.EnemyMovement,BossPayload.Push,"MoonCarry",BossShape.Line,cooldownMillis:BossInkBalance.DarkHandsA0CooldownMillis,mainHits:BossInkBalance.DarkHandsA0MainHits,rangeMilli:BossInkBalance.DarkHandsA0RangeMilli,widthMilli:BossInkBalance.DarkHandsA0WidthMilli,magnitudeMilli:BossInkBalance.DarkHandsA0MagnitudeMilli,element:BossElement.Dark)),
            InkProfile(false,"feet","移動が終わってから2秒以内に行う次の通常攻撃が命中したとき、到達地点の幻影が0.4秒間予告をした後、命中方向へ長さ5m・幅1mの直線状に攻撃力・魔力の高い方の25%のダメージを与える。再発動まで4秒かかり、実体は伴わない。", "When your next basic attack within 2 seconds after movement ends hits, an illusion at your arrival location shows a warning for 0.4 seconds, then deals damage toward the hit direction along a line 5m long and 1m wide, equal to 25% of whichever is higher: your Attack or Ability Power. Cooldown: 4 seconds. The illusion has no physical body.", "移动结束后2秒内的下一次通常攻击命中时，到达地点的幻影显示0.4秒的预警，随后向命中方向沿长5m、宽1m的直线造成相当于攻击力与法术强度中较高一方25%的伤害。冷却4秒，幻影没有实体。",new[]{InkChannel("MoonArrival",BossInkBalance.MoonArrivalValue)},
                new BossAction(BossEvent.MovementCompleted,BossMechanism.Ledger,BossPayload.ArrivalWindow,lifetimeMillis:BossInkBalance.DarkFeetA0LifetimeMillis),
                new BossAction(BossEvent.MainHit,BossMechanism.ShapeAttack,BossPayload.Damage,"MoonArrival",BossShape.Line,cooldownMillis:BossInkBalance.DarkFeetA1CooldownMillis,delayMillis:BossInkBalance.DarkFeetA1DelayMillis,maxInstances:BossInkBalance.DarkFeetA1MaxInstances,rangeMilli:BossInkBalance.DarkFeetA1RangeMilli,widthMilli:BossInkBalance.DarkFeetA1WidthMilli,element:BossElement.Dark)),
            InkProfile(false,"stage2","通常攻撃が命中するごとに、刃、槍、槌の順に派生していく。刃は前方4m・角度90°に攻撃力・魔力の高い方の25%、槍は長さ7m・幅0.8mに攻撃力・魔力の高い方の25%、槌は0.6秒の予告の後、半径2.5mに攻撃力・魔力の高い方の40%のダメージを与える。派生は刃から始まり、6秒間派生しないとリセットされる。再発動まで1秒かかり、その間は進行も蓄積もしない。", "Basic attack hits cycle through blade, spear, and hammer in order: a forward blade with a 4m range and a 90-degree angle dealing 25% of whichever is higher: your Attack or Ability Power; a spear along a line 7m long and 0.8m wide dealing 25%; then a hammer in a 2.5m radius after a 0.6-second warning dealing 40%. Cooldown: 1 second. Hits during the cooldown cannot advance or accumulate progress. Start with the blade; reset after 6 seconds without triggering a form.", "通常攻击每次命中时，按刀刃、长矛、巨锤的顺序切换派生攻击。刀刃对前方4m、角度90°的范围造成相当于攻击力与法术强度中较高一方25%的伤害；长矛对长7m、宽0.8m的直线造成25%的伤害；巨锤在0.6秒预警后对半径2.5m范围造成40%的伤害。从刀刃开始，6秒内未触发派生则重置。冷却1秒，期间无法推进或积累进度。",new[]{InkChannel("MoonForm",BossInkBalance.MoonFormValue),InkChannel("MoonFormHammer",BossInkBalance.MoonFormHammerValue)},
                new BossAction(BossEvent.MainHit,BossMechanism.ShapeAttack,BossPayload.Damage,"MoonForm",BossShape.Fan,cooldownMillis:BossInkBalance.DarkStage2A0CooldownMillis,counterLifetimeMillis:BossInkBalance.DarkStage2A0CounterLifetimeMillis,count:BossInkBalance.DarkStage2A0Count,rangeMilli:BossInkBalance.DarkStage2A0RangeMilli,angleMilli:BossInkBalance.DarkStage2A0AngleMilli,element:BossElement.Dark),
                new BossAction(BossEvent.MainHit,BossMechanism.ShapeAttack,BossPayload.Damage,"MoonForm",BossShape.Line,rangeMilli:BossInkBalance.DarkStage2A1RangeMilli,widthMilli:BossInkBalance.DarkStage2A1WidthMilli,element:BossElement.Dark),
                new BossAction(BossEvent.MainHit,BossMechanism.ShapeAttack,BossPayload.Damage,"MoonFormHammer",anchor:BossAnchor.Hit,delayMillis:BossInkBalance.DarkStage2A2DelayMillis,maxInstances:BossInkBalance.DarkStage2A2MaxInstances,radiusMilli:BossInkBalance.DarkStage2A2RadiusMilli,element:BossElement.Dark)),
            InkProfile(false,"stage3","2セット効果が命中した敵1体に「月印」を付与する。月印は最大3蓄積で、持続は6秒。3蓄積になると印を消費し、0.3秒後に攻撃力・魔力の高い方の30%の斬撃ダメージを与える。再発動まで3秒かかり、別の敵に命中させると古い印は消える。また、移動が終わったときは派生を1段階進める。こちらは再発動まで2秒かかり、コンボはリセットされる。移動そのものではダメージは発生しない。", "When the 2-piece effect hits, apply a Moon Mark to one enemy, lasting 6 seconds and stacking up to 3 times. At 3 stacks, consume the marks and deal slash damage after 0.3 seconds equal to 30% of whichever is higher: your Attack or Ability Power. Cooldown: 3 seconds. Hitting a different enemy removes the old marks. Also advance one form when movement ends. Cooldown: 2 seconds. This resets the combo, and movement itself deals no damage.", "2件套效果命中时，为1名敌人施加“月印”，最多3层，持续6秒。达到3层时消耗印记，0.3秒后造成相当于攻击力与法术强度中较高一方30%的斩击伤害。冷却3秒，命中其他敌人会清除旧印记。此外移动结束时，派生攻击推进1阶段，冷却2秒，并重置连招。移动本身不会造成伤害。",new[]{InkChannel("MoonMark",BossInkBalance.MoonMarkValue)},
                new BossAction(BossEvent.MainHit,BossMechanism.ShapeAttack,BossPayload.Damage,"MoonMark",anchor:BossAnchor.Hit,cooldownMillis:BossInkBalance.DarkStage3A0CooldownMillis,delayMillis:BossInkBalance.DarkStage3A0DelayMillis,lifetimeMillis:BossInkBalance.DarkStage3A0LifetimeMillis,mainHits:BossInkBalance.DarkStage3A0MainHits,maxTargets:BossInkBalance.DarkStage3A0MaxTargets,maxInstances:BossInkBalance.DarkStage3A0MaxInstances,element:BossElement.Dark),
                new BossAction(BossEvent.MovementCompleted,BossMechanism.Ledger,BossPayload.Mode,cooldownMillis:BossInkBalance.DarkStage3A1CooldownMillis,count:BossInkBalance.DarkStage3A1Count)),
            InkProfile(false,"stage6","6秒以内に「刃→槍→槌」の連携を完了させると、槌の地点の左右2mに幻影が現れる。0.35秒後に、それぞれの幻影から長さ6m・幅0.8mの斬撃線が放たれ、攻撃力・魔力の高い方の45%（合計90%、上限100%）のダメージを与える。さらに0.8秒後、半径3mに攻撃力・魔力の高い方の38%（上限40%）の槌ダメージを与える。再発動まで6秒かかり、移動で順序を飛ばすと連携はリセットされる。幻影は召喚物ではなく、実体を伴わない。", "Complete the blade–spear–hammer combo within 6 seconds to create illusions 2m to either side of the hammer location. After 0.35 seconds, each releases a slash along a line 6m long and 0.8m wide, dealing 45% of whichever is higher: your Attack or Ability Power (90% total, cap: 100%). After a further 0.8 seconds, deal hammer damage in a 3m radius equal to 38% (cap: 40%). Cooldown: 6 seconds. Skipping a form through movement resets the combo. The illusions are not summons and have no physical bodies.", "6秒内完成“刀刃→长矛→巨锤”连招时，在巨锤地点左右2m处生成幻影。0.35秒后，各幻影释放长6m、宽0.8m的斩击线，造成相当于攻击力与法术强度中较高一方45%的伤害（合计90%，上限100%）。再过0.8秒，对半径3m范围造成相当于攻击力与法术强度中较高一方38%（上限40%）的锤击伤害。冷却6秒，借助移动跳过派生顺序会重置连招。幻影不视为召唤物，也没有实体。",new[]{InkChannel("MoonPhantom",BossInkBalance.MoonPhantomValue,BossInkBalance.MoonPhantomCap),InkChannel("MoonFinish",BossInkBalance.MoonFinishValue,BossInkBalance.MoonFinishCap)},
                new BossAction(BossEvent.MainHit,BossMechanism.ShapeAttack,BossPayload.Damage,"MoonPhantom",BossShape.Line,cooldownMillis:BossInkBalance.DarkStage6A0CooldownMillis,delayMillis:BossInkBalance.DarkStage6A0DelayMillis,counterLifetimeMillis:BossInkBalance.DarkStage6A0CounterLifetimeMillis,count:BossInkBalance.DarkStage6A0Count,maxInstances:BossInkBalance.DarkStage6A0MaxInstances,rangeMilli:BossInkBalance.DarkStage6A0RangeMilli,widthMilli:BossInkBalance.DarkStage6A0WidthMilli,magnitudeMilli:BossInkBalance.DarkStage6A0MagnitudeMilli,element:BossElement.Dark),
                new BossAction(BossEvent.MainHit,BossMechanism.ShapeAttack,BossPayload.Damage,"MoonFinish",delayMillis:BossInkBalance.DarkStage6A1DelayMillis,maxInstances:BossInkBalance.DarkStage6A1MaxInstances,radiusMilli:BossInkBalance.DarkStage6A1RadiusMilli,element:BossElement.Dark)),
        };
        internal static BossRewardProfile[] CreateInkRewards()
        {
            BossRewardStage White(int stage,int conversion,int slots,int target,int budget) => new BossRewardStage(stage,
                new Txt($"本体の光線による実際の超過回復量の{conversion/10}%を、2秒間の障壁に変換する。対象は先着のヒーロー（自身を含む）{slots}人。障壁の上限は対象ごとに攻撃力・魔力の高い方の{target/10}%で、光線の詠唱1回ごとの合計上限は攻撃力・魔力の高い方の{budget/10}%。障壁を更新したときも、この上限枠を消費する。本体の回復量は減少しない。すべての白夜セットの障壁は最大値で上書きされ、上限は攻撃力・魔力の高い方の38%である。",$"Convert {conversion/10}% of the beam's actual overhealing into a shield lasting 2 seconds for the first {slots} heroes, including you. Each hero's shield is capped at {target/10}% of whichever is higher: your Attack or Ability Power. The total shield allowance per beam cast is {budget/10}% of that value; shield updates also use this allowance. The beam's healing is not reduced. All White Night set shields replace one another with the highest value, capped at 38% of whichever is higher: your Attack or Ability Power.", $"将原有光线实际溢出治疗量的{conversion/10}%转换为持续2秒的护盾，作用于最先接触的{slots}名英雄（包括自身）。每名英雄的护盾上限为攻击力与法术强度中较高一方的{target/10}%，每次光线施放的护盾总额度为该值的{budget/10}%，刷新护盾也会消耗额度。不会减少原有光线的治疗量。所有白夜套装护盾均以最高值覆盖，上限为攻击力与法术强度中较高一方的38%。"),
                new[]{new BossRewardAction(BossRewardActionKind.NativeShield,conversion,conversion,durationMillis:BossInkBalance.WhiteShieldDurationMillis,count:slots,targetCapMilli:target,budgetMilli:budget)});
            BossRewardStage Dark(int stage,int dwell,int flat,int budget)
            {
                var actions = new List<BossRewardAction>{new BossRewardAction(BossRewardActionKind.NativeDamage,flat,flat,BossInkBalance.DarkCooldownMillis,count:BossInkBalance.DarkCount,dwellMillis:dwell,gapToleranceMillis:BossInkBalance.DarkGapToleranceMillis,budgetMilli:budget,magnitudeMilli:BossInkBalance.DarkMagnitude)};
                if(stage>=2) actions.Add(new BossRewardAction(BossRewardActionKind.NativeTarget,BossInkBalance.DarkSpearValue,BossInkBalance.DarkSpearValue,BossInkBalance.DarkSpearCooldownMillis,count:BossInkBalance.DarkSpearCount,rangeMilli:BossInkBalance.DarkSpearRangeMilli,order:1,speedMilli:BossInkBalance.DarkSpearSpeedMilli,widthMilli:BossInkBalance.DarkSpearWidthMilli));
                if(stage>=3) actions.Add(new BossRewardAction(BossRewardActionKind.NativeMode,cooldownMillis:BossInkBalance.DarkModeCooldownMillis,count:BossInkBalance.DarkModeCount,order:2));
                return new BossRewardStage(stage,new Txt($"同じ敵に本体の光線が{dwell/1000.0:0.##}秒間続けて命中した後、その敵への次の光線ダメージに、攻撃力・魔力の高い方の{flat/10}%の追加ダメージを与える。再発動まで1秒かかる。光線1回につき最大3回までで、合計上限は{budget/10}%、対象は最大3体までである。"+(stage>=2?"また、光線が命中したときは、継続時間とは別に投槍を放つ。投槍の弾速は12m/秒、長さは8m、幅は0.5mで、攻撃力・魔力の高い方の25%のダメージを与える。再発動まで1秒かかり、光線1回につき最大3本までである。":"")+(stage>=3?"さらに光線が命中したときは、別に通常攻撃扱いの2セット派生を放つ。再発動まで1秒かかり、光線1回につき最大6回までである。2セット効果と再発動までの時間を共有し、進むのは派生、月印、コンボだけで、部位装備の攻撃回数には数えない。":""),$"After the beam hits the same enemy continuously for {dwell/1000.0:0.##} seconds, its next damage to that enemy deals additional damage equal to {flat/10}% of whichever is higher: your Attack or Ability Power. Cooldown: 1 second. Each beam cast can trigger this up to 3 times, with a total cap of {budget/10}%, for up to 3 enemies. "+(stage>=2?"Also, when the beam hits, independently of the continuous-hit duration, throw a spear at 12m/s along a path 8m long and 0.5m wide, dealing 25% of whichever is higher: your Attack or Ability Power. Cooldown: 1 second, up to 3 spears per beam cast. ":"")+(stage>=3?"Also, when the beam hits, independently trigger a 2-piece attack form treated as a basic attack. Cooldown: 1 second, shared with the 2-piece effect, up to 6 times per beam cast. This advances only attack forms, Moon Marks, and the combo; it does not count toward equipment-piece attack counters.":""), $"原有光线持续命中同一敌人{dwell/1000.0:0.##}秒后，下次对该敌人造成光线伤害时，追加相当于攻击力与法术强度中较高一方{flat/10}%的伤害。冷却1秒，每次光线最多触发3次，总上限为{budget/10}%，最多作用于3名敌人。"+(stage>=2?"此外光线命中时，无论持续命中时间如何，均独立投出长矛。长矛弹速12m/秒，长8m，宽0.5m，造成相当于攻击力与法术强度中较高一方25%的伤害。冷却1秒，每次光线最多投出3支。":"")+(stage>=3?"此外光线命中时，独立触发视为通常攻击的2件套派生攻击。冷却1秒，与2件套效果共享，每次光线最多触发6次。仅推进派生攻击、月印和连招，不计入各部位装备的攻击次数。":"")),actions);
            }
            return new[]{new BossRewardProfile(WhiteNightRewardId,WhiteNightSetId,"St_U_BeamOfBalance",BossRewardAdapter.BeamOfBalance,new[]{White(1,BossInkBalance.RewardWhiteStage1Conversion,BossInkBalance.RewardWhiteStage1Slots,BossInkBalance.RewardWhiteStage1Target,BossInkBalance.RewardWhiteStage1Budget),White(2,BossInkBalance.RewardWhiteStage2Conversion,BossInkBalance.RewardWhiteStage2Slots,BossInkBalance.RewardWhiteStage2Target,BossInkBalance.RewardWhiteStage2Budget),White(3,BossInkBalance.RewardWhiteStage3Conversion,BossInkBalance.RewardWhiteStage3Slots,BossInkBalance.RewardWhiteStage3Target,BossInkBalance.RewardWhiteStage3Budget)}),new BossRewardProfile(DarkMoonRewardId,DarkMoonSetId,"St_U_BeamOfBalance",BossRewardAdapter.BeamOfBalance,new[]{Dark(1,BossInkBalance.RewardDarkStage1DwellMillis,BossInkBalance.RewardDarkStage1Flat,BossInkBalance.RewardDarkStage1Budget),Dark(2,BossInkBalance.RewardDarkStage2DwellMillis,BossInkBalance.RewardDarkStage2Flat,BossInkBalance.RewardDarkStage2Budget),Dark(3,BossInkBalance.RewardDarkStage3DwellMillis,BossInkBalance.RewardDarkStage3Flat,BossInkBalance.RewardDarkStage3Budget)})};
        }
        public static UniqueDef[] CreateInkPieces()
        {
            var result = new List<UniqueDef>();
            void Add(string set,string slot,string baseId,string ja,string en,string zh) => result.Add(new UniqueDef(set+"."+slot,baseId,new Txt(ja,en,zh),set,set.Substring(4)+"."+slot));
            Add(WhiteNightSetId,"weapon","weapon.pilgrim_staff","白蓮の錫杖","White Lotus Staff", "白莲锡杖");
            Add(WhiteNightSetId,"armor","armor.prayer_shawl","安息域の法衣","Haven Robe", "安息领域法衣");
            Add(WhiteNightSetId,"charm","charm.lotus_seal","光秤の印","Lightscale Seal", "光秤之印");
            Add(WhiteNightSetId,"head","head.radiant_halo","白暁の冠","White Dawn Crown", "白晓之冠");
            Add(WhiteNightSetId,"hands","hands.radiant_wraps","蓮掌の手巻き","Lotus Palm Wraps", "莲掌手缠");
            Add(WhiteNightSetId,"feet","feet.dawn_steps","光界の歩み","Lightward Steps", "光界之步");
            Add(DarkMoonSetId,"weapon","weapon.tide_trident","黒月の三叉刃","Black Moon Trident", "黑月三叉刃");
            Add(DarkMoonSetId,"armor","armor.shadow_cloak","怒影の鎧","Wrathshadow Mail", "怒影之铠");
            Add(DarkMoonSetId,"charm","charm.shadow_ring","月欠けの環","Waning Moon Ring", "残月之环");
            Add(DarkMoonSetId,"head","head.raven_mask","自我の面","Mask of the Self", "自我之面");
            Add(DarkMoonSetId,"hands","hands.shadow_gloves","切替の握り","Shifting Grips", "切换之握");
            Add(DarkMoonSetId,"feet","feet.shadow_slippers","跳影の靴","Shadowleap Boots", "跃影之靴");
            return result.ToArray();
        }
        public static SetDef[] CreateInkSets()
        {
            SetDef Set(string id,string ja,string en,string zh,string boss,string reward) => new SetDef
            {
                Id=id,Name=new Txt(ja,en,zh),BossTypeName=boss,BossReward=reward,
                TwoPiece=Array.Empty<StatLine>(),ThreePiece=Array.Empty<PowerLine>(),SixPiece=Array.Empty<PowerLine>(),
                BossStages=new[]{new BossSetStage(2,id.Substring(4)+".stage2"),new BossSetStage(3,id.Substring(4)+".stage3"),new BossSetStage(6,id.Substring(4)+".stage6")},
                LinkStages=new[]
                {
                    new SetLinkStage(2,new LinkDef{Kind=LinkKind.BossReward,Value=1,Requires=new[]{"St_U_BeamOfBalance"}}),
                    new SetLinkStage(4,new LinkDef{Kind=LinkKind.BossReward,Value=2,Requires=new[]{"St_U_BeamOfBalance"}}),
                    new SetLinkStage(6,new LinkDef{Kind=LinkKind.BossReward,Value=3,Requires=new[]{"St_U_BeamOfBalance"}}),
                },
            };
            return new[]{Set(WhiteNightSetId,"白蓮の守装","White Lotus Vestments", "白莲守装","Mon_Ink_BossWhiteNight",WhiteNightRewardId),Set(DarkMoonSetId,"黒月の刃装","Black Moon Armament", "黑月刃装","Mon_Ink_BossDarkMoon",DarkMoonRewardId)};
        }
    }
